def weapons(me, enemy, arena):
    # Weapon priority: lifter first for control, then flipper, then spinner
    # Check if lifter can engage
    if me.weapons.get("lifter", {}).get("state", "") == "up":
        # Lifter is already up - try to keep it up or lower it
        if enemy.z > 0.3 or abs(enemy.x - me.x) > 2.5:
            # Enemy is too high or too far - lower lifter
            return "lower(lifter)"
        else:
            # Enemy is in position - keep lifter up
            return None

    # Try to lift enemy if conditions are right
    if me.weapons.get("lifter", {}).get("state", "") == "down":
        # Check if enemy is in lifting position
        if enemy.z < 0.3 and abs(enemy.x - me.x) < 2.0 and enemy.on_side == False:
            # Enemy is low enough and in front - try to lift
            return "lift(lifter)"
        else:
            # Not in position - just spin up spinner if available
            if me.weapons.get("back", {}).get("rpm", 0) < 100:
                return "spin(back, 3000)"

    # Flipper option - use when enemy is airborne or we can get a good throw
    if me.weapons.get("front", {}).get("shots_left", 0) > 0:
        if enemy.airborne or enemy.z > 0.5:
            # Enemy is in air or high up - try flip
            return "flip(front)"

    # Spinner attack - use when spinner is up to speed
    if me.weapons.get("back", {}).get("rpm", 0) > 500:
        return "spin(back, 3000)"

    # Default: no weapon action
    return None

def drive(me, enemy, arena):
    # Simple proportional pursuit with modest aggression.
    bearing = bearing_to(enemy.x, enemy.y)   # degrees left of heading
    distance = distance_to(enemy.x, enemy.y)

    # Base throttle: full ahead when far, slow down when close.
    base = 1.0 if distance > 1.0 else 0.6

    # Steering towards target.
    turn = 0.0
    if bearing > 10:
        turn = -0.5   # need to turn left
    elif bearing < -10:
        turn = 0.5    # need to turn right
    elif bearing > 3:
        turn = -0.2
    elif bearing < -3:
        turn = 0.2

    left = base + turn
    right = base - turn

    # Back off a bit if we get too close.
    if distance < 0.5:
        left *= 0.5
        right *= 0.5

    # Clamp to allowed range.
    left = max(-1.0, min(1.0, left))
    right = max(-1.0, min(1.0, right))
    return (left, right)


