            cmds.append(spin('back', max_rpm))

    # Fire the flipper when enemy is within range and ready.
    fl = me.weapons.get('front')
    if fl and fl.get('type') == 'flipper':
        if distance_to(enemy.x, enemy.y) < 1.0 and fl.get('ready', False) and fl.get('shots_left', 0) > 0:
            cmds.append(flip('front'))

    # Use the left lifter to lift the enemy when they are stationary and near the left side.
    lif = me.weapons.get('left')
    if lif and lif.get('type') == 'lifter':
        # Approximate left side bearing ~ +90 degrees.
        if abs(bearing_to(enemy.x, enemy.y) - 90) < 30 and enemy.speed < 0.2:
            # If not already lifting, command lift.
            if lif.get('state') != 'up' and not lif.get('engaged', False):
                cmds.append(lift('left'))
        else:
            # Lower if we are not in a good position to lift.
            if lif.get('state') == 'up':
                cmds.append(lower('left'))

    return cmds if cmds else None

